class Solution {
  public int minimumLength(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) count[s.charAt(i) - 'a']++;
    int answer = 0;
    for (int value : count) {
      if (value > 0) answer += (value & 1) == 0 ? 2 : 1;
    }
    return answer;
  }
}
